function getDefaultAdminID() {
	global $fmdb;

	$result = $fmdb->query("SELECT user_id FROM `fm_users` WHERE `user_auth_type`=1 ORDER BY user_id ASC LIMIT 1");

	return $fmdb->last_result[0]->user_id;
