		args args
	}
	tests := []testCase{
		{
			name: "add multiple",
			s:    NewIDSet(),
			args: args{ids: []ID{1, 2, 3}},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
