			name: "contains all",
			s:    NewIDSet(1, 2, 3),
			args: args{ids: []ID{1, 2}},
			want: true,
		},
		{
			name: "contains none",
			s:    NewIDSet(1, 2, 3),
			args: args{ids: []ID{97, 98}},
			want: false,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.want, tt.s.ContainsAny(tt.args.ids...), fmt.Sprintf("ContainsAny(%v)", tt.args.ids))
		})
	}
}
