            $response['asset'] = [
                'id' => $res['asset']->getId(),
                'path' => $res['asset']->getFullPath(),
                'type' => $res['asset']->getType(),
            ];
        }

        return $this->adminJson($response);
    } catch (\Exception $e) {
        return $this->adminJson([
            'success' => false,
            'message' => $e->getMessage(),
        ]);
    }
}
