 * @param  array $attributes
 * @return bool
 */
public function update_attributes( $attributes ) {

	if ( ! is_array( $attributes ) )
		return false;

	$request = filter_input_array(INPUT_POST); // Do this for security reasons

	foreach ( $attributes as $key => $value ) {
		if ( is_array($value) ) {
