			$unique = isset($property['unique']) && $property['unique'] ? 'UNIQUE' : '';
			$sql = 'ALTER TABLE `' . static::table_name() . '` ADD ' . $unique . ' INDEX `' . $property['name'] . '` (' . $property['name'] . $length . ')';
			$wpdb->query( $sql );
