	global $wpdb;

	if ( $this->$p !== null && $this->$p !== '' ) {
		return sprintf( "%s = '%s'", $p, ( is_array($this->$p) ? serialize($this->$p) : $this->$p ) );
	} else {
		return "$p = NULL";
	}
}

