    }

    // Bulk delete action
    if ('bulk_delete' == $current_action) {
        $get_ids = array_map('sanitize_text_field', $_GET['id']);
        foreach ($get_ids as $id) {
            $this->db->delete($this->tb_prefix . "sms_subscribes", ['ID' => intval($id)], ['%d']);
