	var StdSelectorInitParams struct {
		ID []int `json:"id"`
	}

	_ = c.ctx.ShouldBindJSON(&StdSelectorInitParams)
	if len(StdSelectorInitParams.ID) > 0 {
		c.GormScope(func(tx *gorm.DB) *gorm.DB {
			return tx.Where(c.itemKey+" IN ?", StdSelectorInitParams.ID)
		})
	}
}

