function getTopHeader($help) {
	global $fm_login, $__FM_CONFIG;
	include(ABSPATH . 'fm-modules' . DIRECTORY_SEPARATOR . 'facileManager' . DIRECTORY_SEPARATOR . 'variables.inc.php');
