function getCurrentUserMenu() {
	global $menu, $submenu;

	$filtered_menus = array(null, null);

	/** Submenus */
	foreach ($submenu as $slug => $submenu_array) {
		ksort($submenu_array);
		$filtered_menus[1][$slug] = array_filter($submenu_array, 'filterMenu');
