					if (!empty($submenu_array[0])) {
						$submenu_class = ($submenu_array[4] == $GLOBALS['basename']) ? ' class="current"' : null;
						if ($submenu_array[6]) {
							if ($submenu_array[6] > 100) {
								$submenu_array[6] = '99+';
