 */
function basicGetList($table, $id = 'id', $prefix = '', $sql = null, $limit = null, $ip_sort = false, $direction = 'ASC', $count_only = false) {
	global $fmdb;

	switch($sql) {
		case 'active':
			$sql = "AND `{$prefix}status`='active'";
			break;
		default:
			break;
	}

	if (is_array($id)) {
		$primary_field = sanitize($id[0]);
		$secondary_fields = implode(" $direction,", $id);
