private _areHeadingsEqual(headings1: H[], headings2: H[]): boolean {
if (headings1.length === headings2.length) {
    for (let i = 0; i < headings1.length; i++) {
    if (!this.isHeadingEqual(headings1[i], headings2[i])) {
        return false;
    }
