protected function actionSaveAttachmentToTmp($params) {

    $tmpFolder = \GO\Files\Model\Folder::model()->tmpFolder();
    foreach($tmpFolder->files as $file) {
        //clean up older temp files
        if($file->mtime < strtotime("-4 hours")) {
            $file->delete(true);
        }
    }

    $params['filename'] = \GO\Base\Fs\File::stripInvalidChars($params['filename']);
    $file = new \GO\Base\Fs\File(\GO::config()->file_storage_path . $tmpFolder->path.'/'.$params['filename']);
    $file->parent()->create();

    if(empty($params['tmp_file'])){
        $account = Account::model()->findByPk($params['account_id']);
        $imap = $account->openImapConnection($params['mailbox']);
        if(!$imap->save_to_file($params['uid'], $file->path(), $params['number'], $params['encoding'])) {
            throw new Exception("Could not save file from IMAP");
        }
    }else
    {
        $tmpfile = new \GO\Base\Fs\File(\GO::config()->tmpdir.$params['tmp_file']);
        $file = $tmpfile->copy($file->parent(), $file->name());
        if(!$file) {
            throw new Exception("IO error");
        }
    }
    $maxLength = go()->getDatabase()->getTable("fs_files")->getColumn("name")->length;
    $file->shortenFileName($maxLength);

    $dbFile = $tmpFolder->hasFile($file->name());
    if($dbFile) {
        File::$deleteInDatabaseOnly = true;
        $dbFile->delete();
    }
    $dbFile = $tmpFolder->addFile($file->name(), true);

    return ['success' => true, 'data' => $dbFile->getAttributes()];
}
protected function beforeSubmit(&$response, &$model, &$params) {

    if(isset($params['name'])){		
        $params['name'] = \GO\Base\Fs\File::stripInvalidChars($params['name']); // Strip invalid chars
        if(isset($params['extension'])) {
            $params['name'].='.'.$params['extension'];
            $model->extension = $params['extension'];
        } else if(!empty($model->fsFile->extension())) {
            $params['name'].='.'.$model->fsFile->extension();
        }
    }

    if(isset($params['lock'])){
        //GOTA sends lock parameter It does not know the user ID.
        $model->locked_user_id=empty($params['lock']) ? 0 : \GO::user()->id;
    }


    $fh = \GO\Files\Model\FileHandler::model()->findByPk(array(
        'extension' => strtolower($model->extension), 
        'user_id' => \GO::user()->id
    ));

    if(!$fh)
        $fh = new \GO\Files\Model\FileHandler();

    $fh->extension=strtolower($model->extension);

    if(isset($params['handlerCls']))
        $fh->cls=$params['handlerCls'];

    if(empty($params['handlerCls']))
        $fh->delete();
    else
        $fh->save();

    return parent::beforeSubmit($response, $model, $params);
}
