protected function actionHandlers($params){
    if(!empty($params['path'])){
        $folder = \GO\Files\Model\Folder::model()->findByPath(dirname($params['path']));
        $file = $folder->hasFile(\GO\Base\Fs\File::utf8Basename($params['path']));
