    $comment = new Comments($faqConfig);
    $success = false;

    $commentIds = $deleteData->data->{'comments[]'} ?? [];

    if (!is_null($commentIds)) {
        if (!is_array($commentIds)) {
            $commentIds = [$commentIds];
