		Mode:    0644,
		Size:    int64(len(body)),
		ModTime: time.Now(),
	}
	if err := out.WriteHeader(h); err != nil {
		return err
	}
	_, err := out.Write(body)
	return err
}
func getOutDir(basePath, name string) string {
	outdir := filepath.Join(basePath, name)
	return outdir
}
