		// closed, ignore the error.
		if closeErr := d.file.Close(); !errors.Is(closeErr, os.ErrClosed) {
			return n, closeErr
		}
	}
	return n, err
}

func (d *lazyBoundedReadCloser) openFile() error {
	if d.reader != nil {
		return nil
	}

	file, err := os.Open(d.path)
